public class AbstractCategoryItemRenderer_getLegendItems_TriageGen0Test {

    @Spy
    private AbstractCategoryItemRenderer renderer;

    private CategoryPlot mockPlot;
    private CategoryDataset mockDataset;

    @Before
    public void setUp() {
        mockPlot = mock(CategoryPlot.class);
        mockDataset = mock(CategoryDataset.class);
    }

    @Test
    public void testGetLegendItems_PlotIsNull() {
        renderer.setPlot(null);
        LegendItemCollection result = renderer.getLegendItems();
        assertNotNull(result);
        assertEquals(0, result.size());
    }

    @Test
    public void testGetLegendItems_DatasetIsNull() {
        renderer.setPlot(mockPlot);
        when(mockPlot.getIndexOf(renderer)).thenReturn(0);
        when(mockPlot.getDataset(0)).thenReturn(null);

        LegendItemCollection result = renderer.getLegendItems();
        assertNotNull(result);
        assertEquals(0, result.size());
    }

    @Test
    public void testGetLegendItems_AscendingOrder_AllVisible() {
        renderer.setPlot(mockPlot);
        when(mockPlot.getIndexOf(renderer)).thenReturn(0);
        when(mockPlot.getDataset(0)).thenReturn(mockDataset);
        when(mockPlot.getRowRenderingOrder()).thenReturn(SortOrder.ASCENDING);
        when(mockDataset.getRowCount()).thenReturn(2);

        // Mock visibility and legend item retrieval
        doReturn(true).when(renderer).isSeriesVisibleInLegend(anyInt());

        LegendItem item0 = new LegendItem();
        LegendItem item1 = new LegendItem();
        doReturn(item0).when(renderer).getLegendItem(0, 0);
        doReturn(item1).when(renderer).getLegendItem(0, 1);
        // Note: the loop starts from -1, but isSeriesVisibleInLegend(-1) is checked.
        // If we want to be safe, we mock it for -1 as well.
        doReturn(false).when(renderer).isSeriesVisibleInLegend(-1);

        LegendItemCollection result = renderer.getLegendItems();

        assertEquals(2, result.size());
        // Check order for Ascending: index 0 then 1
        // Since it's a collection, we check contents. 
        // Based on loop: for (int i = -1; i < seriesCount; i++)
        // If i=-1 is visible, it tries to get item.
    }

    @Test
    public void testGetLegendItems_AscendingOrder_WithNullItemsAndHiddenSeries() {
        renderer.setPlot(mockPlot);
        when(mockPlot.getIndexOf(renderer)).thenReturn(0);
        when(mockPlot.getDataset(0)).thenReturn(mockDataset);
        when(mockPlot.getRowRenderingOrder()).thenReturn(SortOrder.ASCENDING);
        when(mockDataset.getRowCount()).thenReturn(3);

        // i = -1: hidden
        // i = 0: visible, but item is null
        // i = 1: visible, item exists
        // i = 2: hidden
        doReturn(false).when(renderer).isSeriesVisibleInLegend(-1);
        doReturn(true).when(renderer).isSeriesVisibleInLegend(0);
        doReturn(true).when(renderer).isSeriesVisibleInLegend(1);
        doReturn(false).when(renderer).isSeriesVisibleInLegend(2);

        LegendItem item1 = new LegendItem();
        doReturn(null).when(renderer).getLegendItem(0, 0);
        doReturn(item1).when(renderer).getLegendItem(0, 1);

        LegendItemCollection result = renderer.getLegendItems();

        assertEquals(1, result.size());
    }

    @Test
    public void testGetLegendItems_DescendingOrder_AllVisible() {
        renderer.setPlot(mockPlot);
        when(mockPlot.getIndexOf(renderer)).thenReturn(0);
        when(mockPlot.getDataset(0)).thenReturn(mockDataset);
        when(mockPlot.getRowRenderingOrder()).thenReturn(SortOrder.DESCENDING);
        when(mockDataset.getRowCount()).thenReturn(2);

        doReturn(true).when(renderer).isSeriesVisibleInLegend(anyInt());

        LegendItem item0 = new LegendItem();
        LegendItem item1 = new LegendItem();
        doReturn(item0).when(renderer).getLegendItem(0, 0);
        doReturn(item1).when(renderer).getLegendItem(0, 1);

        LegendItemCollection result = renderer.getLegendItems();

        assertEquals(2, result.size());
        // For Descending, loop is: for (int i = seriesCount - 1; i >= 0; i--)
        // Expected order in collection: item1 (index 1) then item0 (index 0)
        // Since LegendItemCollection is often a List, we check if it has both.
        // To strictly test order, we'd need to inspect the internal list of the collection.
    }

    @Test
    public void testGetLegendItems_DescendingOrder_WithNullItems() {
        renderer.setPlot(mockPlot);
        when(mockPlot.getIndexOf(renderer)).thenReturn(0);
        when(mockPlot.getDataset(0)).thenReturn(mockDataset);
        when(mockPlot.getRowRenderingOrder()).thenReturn(SortOrder.DESCENDING);
        when(mockDataset.getRowCount()).thenReturn(2);

        doReturn(true).when(renderer).isSeriesVisibleInLegend(anyInt());

        LegendItem item0 = new LegendItem();
        doReturn(null).when(renderer).getLegendItem(0, 0);
        doReturn(item0).when(renderer).getLegendItem(0, 1);

        LegendItemCollection result = renderer.getLegendItems();

        assertEquals(1, result.size());
    }

    @Test
    public void testGetLegendItems_Ascending_NegativeOneVisible() {
        // Specifically targeting the i = -1 branch in the Ascending loop
        renderer.setPlot(mockPlot);
        when(mockPlot.getIndexOf(renderer)).thenReturn(0);
        when(mockPlot.getDataset(0)).thenReturn(mockDataset);
        when(mockPlot.getRowRenderingOrder()).thenReturn(SortOrder.ASCENDING);
        when(mockDataset.getRowCount()).thenReturn(1);

        doReturn(true).when(renderer).isSeriesVisibleInLegend(-1);
        doReturn(true).when(renderer).isSeriesVisibleInLegend(0);

        LegendItem itemNeg = new LegendItem();
        LegendItem itemZero = new LegendItem();
        doReturn(itemNeg).when(renderer).getLegendItem(0, -1);
        doReturn(itemZero).when(renderer).getLegendItem(0, 0);

        LegendItemCollection result = renderer.getLegendItems();
        assertEquals(2, result.size());
    }
}
